"use strict";(globalThis.webpackChunkworkshop_pairprogramming_site=globalThis.webpackChunkworkshop_pairprogramming_site||[]).push([[849],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Introduction","href":"/docs/intro","docId":"intro","unlisted":false},{"type":"link","label":"Agenda","href":"/docs/agenda","docId":"agenda","unlisted":false},{"type":"category","label":"Activities","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Grow and Glow","href":"/docs/activities/grow_and_glow","docId":"activities/grow_and_glow","unlisted":false},{"type":"link","label":"Myth or Fact Game","href":"/docs/activities/myth_or_fact","docId":"activities/myth_or_fact","unlisted":false},{"type":"link","label":"Pair Draw","href":"/docs/activities/pair_draw","docId":"activities/pair_draw","unlisted":false},{"type":"link","label":"Pair Programming Retreat","href":"/docs/activities/pair_programming_retreat","docId":"activities/pair_programming_retreat","unlisted":false}],"href":"/docs/category/activities"},{"type":"category","label":"Glossary","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Baby Steps","href":"/docs/glossary/baby_steps","docId":"glossary/baby_steps","unlisted":false},{"type":"link","label":"Bus Factor","href":"/docs/glossary/bus_factor","docId":"glossary/bus_factor","unlisted":false},{"type":"link","label":"Coding Dojo","href":"/docs/glossary/coding_dojo","docId":"glossary/coding_dojo","unlisted":false},{"type":"link","label":"Coding Styleguide","href":"/docs/glossary/coding_styleguide","docId":"glossary/coding_styleguide","unlisted":false},{"type":"link","label":"Creative Commons Attribution-ShareAlike 3.0 Unported","href":"/docs/glossary/creative_commons_license","docId":"glossary/creative_commons_license","unlisted":false},{"type":"link","label":"Driver/Navigator","href":"/docs/glossary/driver_navigator","docId":"glossary/driver_navigator","unlisted":false},{"type":"link","label":"Dynamic Duo Programming","href":"/docs/glossary/dynamic_duo_programming","docId":"glossary/dynamic_duo_programming","unlisted":false},{"type":"link","label":"Extraversion/Introversion","href":"/docs/glossary/extraversion_introversion","docId":"glossary/extraversion_introversion","unlisted":false},{"type":"link","label":"Fizz Buzz","href":"/docs/glossary/fizzbuzz","docId":"glossary/fizzbuzz","unlisted":false},{"type":"link","label":"Hinge Pairing","href":"/docs/glossary/hinge_pairing","docId":"glossary/hinge_pairing","unlisted":false},{"type":"link","label":"Kata","href":"/docs/glossary/kata","docId":"glossary/kata","unlisted":false},{"type":"link","label":"Knowledge Silo","href":"/docs/glossary/knowledge_silo","docId":"glossary/knowledge_silo","unlisted":false},{"type":"link","label":"Synergies of Pair Programming","href":"/docs/glossary/law_of_two_feet","docId":"glossary/law_of_two_feet","unlisted":false},{"type":"link","label":"Synergies of Pair Programming","href":"/docs/glossary/pair_programming_synergies","docId":"glossary/pair_programming_synergies","unlisted":false},{"type":"link","label":"Law of Two Feet","href":"/docs/glossary/pairing_pod","docId":"glossary/pairing_pod","unlisted":false},{"type":"link","label":"Pairing Stair","href":"/docs/glossary/pairing_stair","docId":"glossary/pairing_stair","unlisted":false},{"type":"link","label":"Pairing Workspaces","href":"/docs/glossary/pairing_workspaces","docId":"glossary/pairing_workspaces","unlisted":false},{"type":"link","label":"Ping Pong Pairing","href":"/docs/glossary/ping_pong_pairing","docId":"glossary/ping_pong_pairing","unlisted":false},{"type":"link","label":"Promiscuous Pairing","href":"/docs/glossary/promiscuous_pairing","docId":"glossary/promiscuous_pairing","unlisted":false},{"type":"link","label":"Regular Commits","href":"/docs/glossary/regular_commits","docId":"glossary/regular_commits","unlisted":false},{"type":"link","label":"7 Habits of Effective Pair Programmers","href":"/docs/glossary/seven_habits_effective_pair_programmers","docId":"glossary/seven_habits_effective_pair_programmers","unlisted":false},{"type":"link","label":"Shu-Ha-Ri","href":"/docs/glossary/shu_ha_ri","docId":"glossary/shu_ha_ri","unlisted":false},{"type":"link","label":"Silent Pairing","href":"/docs/glossary/silent_pairing","docId":"glossary/silent_pairing","unlisted":false},{"type":"link","label":"Strong-Style Pairing","href":"/docs/glossary/strong_style_pairing","docId":"glossary/strong_style_pairing","unlisted":false},{"type":"link","label":"Switch Times","href":"/docs/glossary/switch_times","docId":"glossary/switch_times","unlisted":false},{"type":"link","label":"Synergies of Pair Programming","href":"/docs/glossary/synergies_in_pair_programming","docId":"glossary/synergies_in_pair_programming","unlisted":false},{"type":"link","label":"Test-First Pairing","href":"/docs/glossary/test_first_pairing","docId":"glossary/test_first_pairing","unlisted":false},{"type":"link","label":"Training from the Back of the Room","href":"/docs/glossary/training_from_back_of_the_room","docId":"glossary/training_from_back_of_the_room","unlisted":false},{"type":"link","label":"YAGNI (You Aren\'t Gonna Need It)","href":"/docs/glossary/yagni","docId":"glossary/yagni","unlisted":false}],"href":"/docs/category/glossary"},{"type":"link","label":"The Trainer","href":"/docs/the-trainer","docId":"the-trainer","unlisted":false},{"type":"link","label":"Imprint","href":"/docs/imprint","docId":"imprint","unlisted":false}]},"docs":{"activities/grow_and_glow":{"id":"activities/grow_and_glow","title":"Grow and Glow","description":"This activity provides an ongoing, iterative feedback mechanism to identify what\'s working well (\\"Glow\\") and what needs improvement (\\"Grow\\") during a workshop or training session.","sidebar":"tutorialSidebar"},"activities/myth_or_fact":{"id":"activities/myth_or_fact","title":"Myth or Fact Game","description":"A group activity where statements about pair programming are evaluated as myths or facts. This game reinforces understanding of concepts through debate and clarification.","sidebar":"tutorialSidebar"},"activities/pair_draw":{"id":"activities/pair_draw","title":"Pair Draw","description":"A non-verbal drawing exercise that makes the contrast between solo and collaborative work tangible.","sidebar":"tutorialSidebar"},"activities/pair_programming_retreat":{"id":"activities/pair_programming_retreat","title":"Pair Programming Retreat","description":"This activity is a structured, hands-on workshop modeled on the Coderetreat format, designed to deepen developers\' skills in Test-Driven Development (TDD) and tactical pair programming techniques.","sidebar":"tutorialSidebar"},"agenda":{"id":"agenda","title":"Agenda","description":"Two-Day Workshop Format","sidebar":"tutorialSidebar"},"glossary/baby_steps":{"id":"glossary/baby_steps","title":"Baby Steps","description":"A software development discipline wherein practitioners make the smallest possible incremental change that moves toward a goal while keeping the system in a verifiable, working state. It is a foundational practice for maintaining control and managing complexity during development.","sidebar":"tutorialSidebar"},"glossary/bus_factor":{"id":"glossary/bus_factor","title":"Bus Factor","description":"The Bus Factor is a metric that quantifies the risk associated with knowledge concentration in a project. It is defined as the minimum number of team members who, if they were to suddenly become unavailable, would cause the project to stall or fail due to a loss of critical and unshared knowledge. A low bus factor signifies a high-risk dependency on a small number of individuals, whereas a high bus factor indicates greater knowledge distribution and team resilience.","sidebar":"tutorialSidebar"},"glossary/coding_dojo":{"id":"glossary/coding_dojo","title":"Coding Dojo","description":"Definition","sidebar":"tutorialSidebar"},"glossary/coding_styleguide":{"id":"glossary/coding_styleguide","title":"Coding Styleguide","description":"A Coding Styleguide is a formal documentation that specifies a comprehensive set of rules and conventions for writing and organizing source code within a project or organization. It dictates standards for formatting, naming conventions, architectural patterns, and language-specific best practices to ensure consistency, readability, and maintainability across a codebase.","sidebar":"tutorialSidebar"},"glossary/creative_commons_license":{"id":"glossary/creative_commons_license","title":"Creative Commons Attribution-ShareAlike 3.0 Unported","description":"The Creative Commons Attribution-ShareAlike 3.0 Unported (CC BY-SA 3.0) is a public copyright license that allows for the free distribution and modification of a creative work. Under this legal framework, anyone may use, share, and adapt the work, even for commercial purposes, provided they give appropriate Attribution (BY) to the original creator and distribute any derivative works under the same or a compatible ShareAlike (SA) license.","sidebar":"tutorialSidebar"},"glossary/driver_navigator":{"id":"glossary/driver_navigator","title":"Driver/Navigator","description":"Definition","sidebar":"tutorialSidebar"},"glossary/dynamic_duo_programming":{"id":"glossary/dynamic_duo_programming","title":"Dynamic Duo Programming","description":"Dynamic Duo Programming is the original term, coined by the software engineering pioneer Larry Constantine in the 1990s, for the practice now widely known as Pair Programming. It describes a collaborative development method where two programmers work together at a single workstation, emphasizing the synergistic relationship and complementary skills between the partners to produce higher-quality software.","sidebar":"tutorialSidebar"},"glossary/extraversion_introversion":{"id":"glossary/extraversion_introversion","title":"Extraversion/Introversion","description":"Extraversion and Introversion are two fundamental personality traits that describe a person\'s disposition toward social interaction and environmental stimulation. Extraversion is characterized by a preference for seeking stimulation from the external world, such as social gatherings and collaborative activities. Introversion is characterized by a tendency to draw energy from internal sources, preferring solitude or smaller, more intimate social settings. These traits are not absolute but exist on a spectrum, influencing how individuals work, communicate, and function within professional environments.","sidebar":"tutorialSidebar"},"glossary/fizzbuzz":{"id":"glossary/fizzbuzz","title":"Fizz Buzz","description":"FizzBuzz is a common programming exercise designed to improve fundamental coding competency. The task is to write a program that iterates through a sequence of numbers, typically from 1 to 100, and for each number, prints a specific output based on its divisibility. The rules are: for multiples of three, print \\"Fizz\\"; for multiples of five, print \\"Buzz\\"; for numbers that are multiples of both three and five, print \\"FizzBuzz\\"; otherwise, print the number itself.","sidebar":"tutorialSidebar"},"glossary/hinge_pairing":{"id":"glossary/hinge_pairing","title":"Hinge Pairing","description":"Hinge Pairing is a collaborative software development technique designed to systematically distribute knowledge across a team. The method involves one developer, the hinge developer, who remains on a specific task or codebase for an extended period, while other team members rotate as their partner. This structure uses the hinge as a point of continuity, allowing fresh perspectives to be introduced frequently without losing project context.","sidebar":"tutorialSidebar"},"glossary/kata":{"id":"glossary/kata","title":"Kata","description":"A Kata is a small, repetitive programming exercise designed to hone a developer\'s skills through deliberate practice. Originating from the concept in Japanese martial arts, a programming kata involves solving a well-defined problem multiple times to build muscle memory, internalize design patterns, and achieve fluency in a specific technique or programming language. The focus is on the process of solving the problem, not just the final solution.","sidebar":"tutorialSidebar"},"glossary/knowledge_silo":{"id":"glossary/knowledge_silo","title":"Knowledge Silo","description":"A Knowledge Silo is an organizational anti-pattern where critical information, expertise, or specialized skills related to a system or process are confined to a single individual or a small, isolated group. This hoarding of knowledge, whether intentional or accidental, prevents its dissemination across the wider organization, creating dependencies and impeding collaboration.","sidebar":"tutorialSidebar"},"glossary/law_of_two_feet":{"id":"glossary/law_of_two_feet","title":"Synergies of Pair Programming","description":"Pair Programming is a software development discipline in which two programmers collaborate at a single workstation. One developer, the driver, writes the code, while the other, the navigator, observes, provides real-time review, and focuses on the strategic direction of the work. The roles of driver and navigator are switched frequently. This technique is designed to improve code quality, facilitate knowledge transfer, and foster a shared understanding of the codebase through continuous, real-time collaboration.","sidebar":"tutorialSidebar"},"glossary/pair_programming_synergies":{"id":"glossary/pair_programming_synergies","title":"Synergies of Pair Programming","description":"Definition","sidebar":"tutorialSidebar"},"glossary/pairing_pod":{"id":"glossary/pairing_pod","title":"Law of Two Feet","description":"The Law of Two Feet is a core principle used in self-organizing events, such as unconferences, that empowers participants to take full responsibility for their own learning and engagement. The rule states that if a participant finds themselves in a session where they are neither learning nor contributing, they have the right and the responsibility to use their two feet and move to another session or activity where they can be more productive.","sidebar":"tutorialSidebar"},"glossary/pairing_stair":{"id":"glossary/pairing_stair","title":"Pairing Stair","description":"A Pairing Stair is a visual management tool used by software development teams to track pair programming assignments over time. It typically consists of a physical or digital board that displays a stair-step pattern, with developers\' names moving down the steps as they rotate partners. The primary purpose of this artifact is to make pairing history transparent, ensure balanced rotations, and facilitate the deliberate distribution of knowledge across the team.","sidebar":"tutorialSidebar"},"glossary/pairing_workspaces":{"id":"glossary/pairing_workspaces","title":"Pairing Workspaces","description":"Pairing Workspaces are physical environments specifically designed and equipped to support effective pair programming. These dedicated areas feature ergonomic setups, specialized equipment, and sufficient space to facilitate seamless, comfortable, and productive collaboration between two developers at a single workstation.","sidebar":"tutorialSidebar"},"glossary/ping_pong_pairing":{"id":"glossary/ping_pong_pairing","title":"Ping Pong Pairing","description":"Ping Pong Pairing is a prescribed pair programming technique that synchronizes the practice of Test-Driven Development (TDD) with the switching of roles between two developers. The workflow follows a distinct rhythm: one developer writes a failing test (the \\"ping\\"), and the other developer writes the production code to make that test pass (the \\"pong\\"). This cycle repeats, with roles reversing at each step, ensuring continuous, balanced collaboration.","sidebar":"tutorialSidebar"},"glossary/promiscuous_pairing":{"id":"glossary/promiscuous_pairing","title":"Promiscuous Pairing","description":"Promiscuous Pairing is a disciplined approach to pair programming where team members deliberately and frequently switch partners. The primary goal is to maximize knowledge distribution, accelerate learning, and increase exposure to diverse skills and perspectives by ensuring no two developers are paired together for an extended period.","sidebar":"tutorialSidebar"},"glossary/regular_commits":{"id":"glossary/regular_commits","title":"Regular Commits","description":"Regular Commits is a software development discipline where practitioners commit code changes to a version control system at a high frequency. This practice focuses on capturing small, incremental, and logically consistent units of work. The primary objective is to create a detailed and traceable history of a project\'s evolution, which serves to minimize the risk of data loss, improve team collaboration, and streamline the debugging process.","sidebar":"tutorialSidebar"},"glossary/seven_habits_effective_pair_programmers":{"id":"glossary/seven_habits_effective_pair_programmers","title":"7 Habits of Effective Pair Programmers","description":"The 7 Habits of Effective Pair Programmers is a framework of interpersonal behaviors and professional disciplines considered essential for successful and sustainable pair programming. These habits look beyond technical ability, focusing instead on the communication, trust, and mutual respect required to create a collaborative environment where two developers can perform as a single, cohesive unit. Adherence to these principles directly impacts code quality, knowledge sharing, and team health.","sidebar":"tutorialSidebar"},"glossary/shu_ha_ri":{"id":"glossary/shu_ha_ri","title":"Shu-Ha-Ri","description":"Shu-Ha-Ri is a model that describes the three stages of progression in mastering a skill or discipline. Originating from Japanese martial arts, the framework outlines a learning journey that begins with rigid adherence to established rules (Shu), moves to understanding and innovating upon those rules (Ha), and culminates in transcending the rules to embody the practice and create a personal style (Ri).","sidebar":"tutorialSidebar"},"glossary/silent_pairing":{"id":"glossary/silent_pairing","title":"Silent Pairing","description":"Silent Pairing is a deliberate practice exercise in which two developers collaborate on a task without speaking. The constraint of silence forces participants to rely entirely on non-verbal communication, attentive observation, and the clarity of the code itself to convey intent and direction. It is a pedagogical tool designed to improve communication skills and mutual understanding, not a standard day-to-day working method.","sidebar":"tutorialSidebar"},"glossary/strong_style_pairing":{"id":"glossary/strong_style_pairing","title":"Strong-Style Pairing","description":"Strong-Style Pairing is a structured pair programming discipline governed by a single, definitive rule: \\"For an idea to go from your head into the computer, it MUST go through someone else\'s hands.\\" In this model, the navigator (the person with the idea) verbalizes their thoughts, while the driver translates those instructions into code. This style is explicitly designed to maximize knowledge transfer and is highly effective in mentoring scenarios.","sidebar":"tutorialSidebar"},"glossary/switch_times":{"id":"glossary/switch_times","title":"Switch Times","description":"Switch Times are the predetermined intervals or logical breakpoints at which the driver and navigator roles are exchanged during a pair programming session. The practice of regular and disciplined switching is a core component of effective pairing, designed to ensure balanced participation, maintain high energy levels, and facilitate a shared understanding of the work.","sidebar":"tutorialSidebar"},"glossary/synergies_in_pair_programming":{"id":"glossary/synergies_in_pair_programming","title":"Synergies of Pair Programming","description":"The Synergies of Pair Programming are the emergent, collaborative effects that arise when two developers work together effectively. These phenomena, such as enhanced problem-solving, accelerated learning, and increased courage, allow the pair to achieve outcomes that are greater than the sum of their individual capabilities. They represent the transformation of two programmers into a single, cohesive problem-solving unit.","sidebar":"tutorialSidebar"},"glossary/test_first_pairing":{"id":"glossary/test_first_pairing","title":"Test-First Pairing","description":"A practice where one partner writes a test that intentionally fails, and the other writes code to pass it. This is a form of Test-Driven Development (TDD), encouraging rigorous, quality-focused development.","sidebar":"tutorialSidebar"},"glossary/training_from_back_of_the_room":{"id":"glossary/training_from_back_of_the_room","title":"Training from the Back of the Room","description":"Training from the Back of the Room is a learner-centered instructional design and facilitation methodology where the instructor shifts from being a lecturer to a facilitator. This approach emphasizes participant engagement through structured activities, collaboration, and peer-to-peer teaching, prioritizing practical application and experiential learning over passive information consumption. The core goal is to improve knowledge retention and build practical skills by aligning the training experience with principles of cognitive neuroscience.","sidebar":"tutorialSidebar"},"glossary/yagni":{"id":"glossary/yagni","title":"YAGNI (You Aren\'t Gonna Need It)","description":"A principle in agile software development that encourages avoiding unnecessary features. YAGNI helps teams focus on essential tasks to improve productivity.","sidebar":"tutorialSidebar"},"imprint":{"id":"imprint","title":"Imprint","description":"Information according to \xa7 5 TMG:","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction","description":"This workshop began as an exercise and challenge in turning any engaging topic into an interactive session - Pair Programming was my interest and \'Training from Back of the Room\' had left its impression on me. In 2013, I reached out on Twitter and quickly found volunteers to test the format\u2014heavily inspired by Code Retreats and the then-emerging ensemble-programming movement. Generous feedback helped me refine the content, and improvements were incorporated over the years.","sidebar":"tutorialSidebar"},"the-trainer":{"id":"the-trainer","title":"The Trainer","description":"Sebastian Sch\xfcrmann","sidebar":"tutorialSidebar"}}}}')}}]);